        [1, 9],
        [2, 8],
        [3, 7],
        [4, 6],
    ]


def test_excluded_digits_remove_matching_combinations():
    assert _normalized(combinations(10, 2, [1, 4])) == [[2, 8], [3, 7]]


def test_three_digits_sum_ten_all_combinations_sorted():
    assert _normalized(combinations(10, 3, [])) == [
